enum class RulesGlossaryType {
    BESTIARY,
    SPELLBOOK
}

private data class GlossaryEntry(val term: String, val explanation: String)

@Composable
fun RulesGlossaryDialog(type: RulesGlossaryType, onDismiss: () -> Unit) {
    val title: String
    val introduction: String
    val entries: List<GlossaryEntry>

    when (type) {
        RulesGlossaryType.BESTIARY -> {
            title = "Ajuda do Bestiário"
            introduction = "Consulte as abreviações e os termos usados nas fichas de criaturas de D&D 3.5."
            entries = listOf(
                GlossaryEntry("Ext — Extraordinária", "Habilidade não mágica, embora possa desafiar as leis da física. Não é afetada por dissipar magia, resistência à magia ou campo antimagia. Em geral, não pode ser interrompida como uma magia e não provoca ataques de oportunidade."),
                GlossaryEntry("Sob — Sobrenatural", "Habilidade mágica, mas não funciona como uma magia comum. Não é afetada por resistência à magia, não pode ser dissipada nem usada para contra-atacar magias. É suprimida em campo antimagia. Normalmente exige ação padrão, não provoca ataques de oportunidade e não exige Concentração."),
                GlossaryEntry("SM — Similar à Magia", "Reproduz o efeito de uma magia. Não exige componentes verbais, gestuais ou materiais, foco nem custo de XP. É afetada por resistência à magia e pode ser dissipada; usá-la sob ameaça normalmente provoca ataque de oportunidade. Não funciona em campo antimagia."),
                GlossaryEntry("Habilidade natural", "Capacidade decorrente da natureza física da criatura que não foi identificada como Ext, Sob ou SM. Não se deve presumir que seja mágica apenas por ser incomum."),
                GlossaryEntry("Ataques especiais e qualidades especiais", "Ataques especiais são capacidades usadas para atacar ou prejudicar oponentes. Qualidades especiais abrangem defesas, sentidos, formas de movimento, resistências, vulnerabilidades e outras capacidades que não são propriamente ataques."),
                GlossaryEntry("Usos e frequência", "Indicações como 1/dia, 3/dia ou à vontade informam quantas vezes a habilidade pode ser usada. À vontade significa que não há limite diário, mas o tempo de ativação e outras condições continuam valendo."),
                GlossaryEntry("CD — Classe de Dificuldade", "Número que o alvo precisa alcançar no teste de resistência para evitar ou reduzir um efeito. Use a CD indicada na ficha. Como regra geral, a CD de habilidades de monstros costuma ser 10 + metade dos Dados de Vida raciais + o modificador do atributo relevante."),
                GlossaryEntry("Nível de conjurador", "Determina variáveis de uma habilidade similar à magia que reproduz uma magia, como alcance, duração e dificuldade para dissipar o efeito. Se não for indicado, normalmente é igual aos Dados de Vida da criatura."),
                GlossaryEntry("Dano e dreno de atributo", "Dano de atributo reduz temporariamente um valor; dreno reduz o valor permanentemente até ser restaurado por meios apropriados. Constituição 0 normalmente significa morte; os demais atributos em 0 produzem incapacidades específicas."),
                GlossaryEntry("Dreno de energia", "O ataque absorve energia vital e impõe um ou mais níveis negativos após atingir o alvo; um sucesso decisivo dobra a quantidade. Cada nível negativo impõe –1 em testes de perícia e habilidade, jogadas de ataque e testes de resistência, além de reduzir o nível efetivo ou os DV quando isso afetar um cálculo. O atacante normalmente recebe 5 PV temporários por nível negativo (10 em um sucesso decisivo), por 1 hora. Os níveis duram 24 horas ou até serem removidos; depois desse prazo, cada um exige Fortitude contra a CD do verbete ou causa perda permanente de um nível de classe. Exemplo prático: se um ataque causar dois níveis negativos, a vítima sofre –2 nas jogadas e testes afetados, enquanto o atacante recebe normalmente 10 PV temporários."),
                GlossaryEntry("Veneno", "A ficha informa forma de inoculação, CD de Fortitude e dano inicial e secundário. O dano secundário ocorre depois do intervalo indicado. Criaturas imunes a veneno não são afetadas."),
                GlossaryEntry("Doença", "Pode ser transmitida por ataque, contato, inalação ou outra forma indicada. A descrição informa incubação, CD e dano inicial e secundário."),
                GlossaryEntry("Paralisia", "Este ataque especial imobiliza o corpo: a vítima não pode se mover nem realizar ações físicas, ficando indefesa, embora continue capaz de observar e sentir. O teste costuma ser de Fortitude, com CD e duração indicadas no verbete; diferentemente de alguns efeitos de imobilização, a paralisia não concede novo teste a cada rodada. Uma criatura voadora paralisada cai; uma nadadora pode começar a se afogar. Exemplo prático: se uma criatura alada falhar contra um ataque paralisante enquanto voa, deixa de bater as asas e cai."),
                GlossaryEntry("Olhar", "Ataque visual que afeta criaturas que olham para o usuário, conforme alcance, direção e condições descritas. Desviar os olhos ou fechá-los pode evitar alguns ataques, mas traz as penalidades correspondentes."),
                GlossaryEntry("Sopro", "Ataque especial que normalmente afeta uma área, como cone ou linha, e costuma causar dano de energia. Em geral, Reflexos reduz o dano à metade; a CD básica é 10 + metade dos Dados de Vida raciais + modificador de Constituição do atacante. O verbete fornece a CD exata e pode indicar Fortitude ou Vontade em vez de Reflexos. Salvo indicação contrária, a criatura é imune ao próprio sopro. Exemplo prático: diante de um sopro de fogo em cone, os alvos fazem Reflexos para reduzir o dano, enquanto o próprio dragão não é ferido pelo seu sopro."),
                GlossaryEntry("Agarrar aprimorado", "Quando a criatura acerta o ataque indicado, pode iniciar um agarrão sem provocar ataque de oportunidade e sem realizar o ataque de toque inicial. A ficha informa quais ataques permitem iniciar o agarrão."),
                GlossaryEntry("Agarrar", "Manobra para imobilizar ou restringir um oponente. Envolve testes resistidos; tamanho, Força e modificadores específicos influenciam o resultado. Estar agarrado limita as ações da vítima."),
                GlossaryEntry("Constrição", "Depois de agarrar e obter sucesso no teste indicado, a criatura esmaga o alvo e causa o dano adicional informado. Algumas criaturas causam esse dano automaticamente a cada rodada em que mantêm o agarrão."),
                GlossaryEntry("Bote", "Permite à criatura realizar um ataque completo ao fim de uma investida, em vez de ficar limitada ao ataque normalmente permitido por uma investida."),
                GlossaryEntry("Rasgar e dilacerar", "Ataques adicionais que causam dano quando a criatura acerta o alvo com os ataques exigidos pela habilidade. A ficha informa a quantidade de ataques necessários e o dano."),
                GlossaryEntry("Atropelar", "A criatura pode passar por cima de oponentes durante seu deslocamento. Os alvos podem realizar ataque de oportunidade com penalidade ou tentar Reflexos para reduzir o dano à metade."),
                GlossaryEntry("Investida poderosa", "Ataque especial realizado ao investir, normalmente causando dano adicional quando a criatura atinge o alvo. O dano e eventuais condições aparecem na descrição da criatura."),
                GlossaryEntry("Engolfar", "A criatura envolve o oponente com o próprio corpo. O alvo pode ficar preso, sofrer dano ou ser submetido a outros efeitos descritos na habilidade."),
                GlossaryEntry("Engolir inteiro", "A criatura pode engolir o alvo após cumprir as condições da habilidade. A vítima sofre os efeitos descritos para o interior do corpo, normalmente dano contínuo, e pode tentar escapar."),
                GlossaryEntry("Enredar e teia", "Uma teia ou substância semelhante pode prender e restringir o movimento. A ficha informa alcance, área, resistência para evitar, CD para escapar e/ou força necessária para romper."),
                GlossaryEntry("Drenar sangue", "A criatura suga sangue de uma vítima agarrada ou indefesa, causando dano ou perda indicada. Algumas habilidades também restauram pontos de vida."),
                GlossaryEntry("Medo e desespero", "São efeitos de ação mental e medo. Podem surgir como aura, cone ou raio; uma aura pode paralisar (como o desespero das múmias) ou reproduzir a magia medo. O verbete determina área, condição, CD e duração. Exemplo prático: ao entrar na área de uma aura de medo, um aventureiro faz o teste de Vontade indicado; se falhar, sofre a condição descrita pela criatura."),
                GlossaryEntry("RD — Redução de Dano", "Subtrai uma quantidade fixa do dano de cada ataque físico que não supere a condição indicada após a barra. Exemplo: RD 5/mágica ignora 5 pontos de dano de armas não mágicas. Não reduz dano de energia."),
                GlossaryEntry("Resistência à energia", "Reduz o dano recebido de um tipo de energia pelo valor indicado, por aplicação de dano. Não concede imunidade: qualquer dano acima da resistência ainda é sofrido."),
                GlossaryEntry("Imunidade à magia", "A criatura ignora magias e habilidades similares à magia que a afetem diretamente, conforme os limites indicados. Diferentemente da Resistência à Magia, essa imunidade não pode ser superada por um teste de nível de conjurador. Magias que não estão sujeitas à Resistência à Magia também ignoram essa imunidade. Exemplo do livro: o golem de barro é imune à maioria das magias sujeitas à RM, mas desintegrar o deixa lento e mover terra o arremessa para longe; portanto, sempre confira as exceções do verbete."),
                GlossaryEntry("Imunidade e vulnerabilidade à energia", "Imunidade impede todo dano do tipo indicado. Vulnerabilidade normalmente aumenta em 50% o dano daquele tipo. A descrição específica pode estabelecer exceções."),
                GlossaryEntry("Cura acelerada", "A criatura recupera automaticamente a quantidade indicada de pontos de vida a cada rodada. Não restaura perdas que não sejam dano, como certas formas de perda de atributo."),
                GlossaryEntry("Regeneração", "O dano sofrido é convertido em dano não letal e a criatura recupera esse dano à taxa indicada. Certos tipos de ataque, especificados na ficha, causam dano letal normalmente. Pode permitir recuperar ou recolocar partes do corpo."),
                GlossaryEntry("Evasão", "Quando obtém sucesso em Reflexos contra um efeito que normalmente causa metade do dano, a criatura não sofre dano algum. Só funciona quando pode aplicar seu bônus de Destreza à CA."),
                GlossaryEntry("Evasão aprimorada", "Funciona como evasão, mas a criatura ainda sofre apenas metade do dano quando falha no teste de Reflexos. Se obtiver sucesso, não sofre dano."),
                GlossaryEntry("RM — Resistência à Magia", "Valor que o conjurador precisa igualar ou superar em um teste de nível de conjurador (1d20 + nível de conjurador). Aplica-se a magias e habilidades similares à magia sujeitas à RM, não a habilidades Ext ou Sob."),
                GlossaryEntry("Resistência à expulsão", "Bônus que aumenta os Dados de Vida efetivos da criatura para resistir a tentativas de expulsar, fascinar, comandar ou fortalecer mortos-vivos, conforme a habilidade."),
                GlossaryEntry("Visão no escuro", "Permite enxergar sem luz dentro do alcance indicado, normalmente em preto e branco. Não permite ver através de escuridão mágica que bloqueie esse sentido, salvo regra específica."),
                GlossaryEntry("Enxergar no escuro (Sob)", "Capacidade sobrenatural específica de certos extra-planares: permite enxergar perfeitamente em trevas de qualquer espécie, inclusive as criadas por escuridão profunda. Não deve ser confundida com a visão no escuro comum."),
                GlossaryEntry("Visão na penumbra", "Permite enxergar melhor sob iluminação fraca, como luar ou luz das estrelas. Não concede visão na escuridão total."),
                GlossaryEntry("Sentido cego", "Permite localizar a presença de criaturas por sentidos não visuais, dentro do alcance indicado e desde que exista linha de efeito. Não elimina todas as limitações da visão: alvos que não consiga perceber ainda podem ter camuflagem total, e a criatura continua sujeita às chances de falha e à perda do bônus de Destreza contra esses adversários. Exemplo do livro: um enxame de morcegos percebe criaturas a até 6 m, mas elas ainda têm camuflagem total contra os morcegos; os ataques do enxame, especificamente, ignoram essa camuflagem."),
                GlossaryEntry("Percepção às cegas", "É mais precisa que o sentido cego: permite perceber, manobrar e lutar normalmente sem visão, usando audição, olfato, vibrações ou ecolocalização. Invisibilidade, escuridão e a maioria das camuflagens não impedem a detecção, mas é necessária linha de efeito. Em geral funciona continuamente; quando exigir ativação, a ficha indicará essa condição. Exemplo prático: um golfinho pode localizar um nadador próximo pela ecolocalização, mesmo em água escura, desde que não haja algo bloqueando a linha de efeito."),
                GlossaryEntry("Faro", "Permite detectar a aproximação de inimigos, farejar oponentes ocultos e rastrear pelo olfato. O alcance básico é 9 m; aumenta para 18 m se o alvo estiver a favor do vento e cai para 4,5 m se estiver contra o vento. Odores fortes podem ser percebidos a duas vezes essa distância e odores extremos a três vezes. Detectar o odor revela a presença, não a localização exata: uma ação de movimento permite determinar a direção e, a até 1,5 m, localizar a fonte. Com o talento Rastrear, a criatura pode seguir rastros pelo cheiro usando Sabedoria ou Sobrevivência; a CD padrão de uma trilha recente é 10 e aumenta em 2 por hora de idade. Exemplo prático: um lobo fareja a presença de aventureiros a favor do vento a até 18 m; isso revela que há criaturas por perto, mas ele ainda precisa farejar a direção e se aproximar para localizá-las."),
                GlossaryEntry("Faro aprimorado", "É uma versão específica indicada em determinados verbetes, não uma regra universal com alcance fixo. O tubarão comum, por exemplo, identifica criaturas pelo olfato a até 60 m e detecta cheiro de sangue na água a até 1,5 km. Sempre use os valores do verbete da criatura."),
                GlossaryEntry("Sentido sísmico", "Permite detectar e localizar criaturas em contato com o mesmo solo ou superfície dentro do alcance indicado. A criatura que usa esse sentido também precisa estar em contato com a superfície."),
                GlossaryEntry("Incorpóreo", "A criatura não possui corpo físico. Em geral, só pode ser ferida por outras criaturas incorpóreas, armas mágicas ou efeitos específicos; atravessa objetos sólidos, mas não efeitos que bloqueiem incorpóreos."),
                GlossaryEntry("Alterar Forma (Sob)", "Permite assumir uma ou mais formas específicas, como a magia metamorfose, mas somente as formas listadas no verbete e sem recuperar PV. A criatura conserva tipo e subtipos, muda de tamanho, recebe Força, Destreza e Constituição da nova forma e mantém Inteligência, Sabedoria e Carisma. Perde armas naturais, armadura natural, deslocamentos e ataques especiais extraordinários da forma original; adquire esses elementos da nova forma. Conserva as qualidades especiais e as habilidades similares à magia e sobrenaturais originais (exceto olhar e sopro), mas não ganha as qualidades especiais, habilidades similares à magia ou ataques sobrenaturais da nova forma. Exemplo do livro: o ghaele alterna entre forma humanoide e forma de globo incorpóreo. Na forma humanoide pode usar o ataque visual, mas não voar nem disparar raios de luz; na forma de globo pode voar e disparar raios, mas não usar o ataque visual nem conjurar magias."),
                GlossaryEntry("Mudar Forma (Sob)", "Permite assumir a aparência de uma criatura ou tipo de criatura, geralmente humanoide, mantendo as próprias qualidades físicas. A nova forma não pode diferir mais de uma categoria de tamanho. A criatura conserva tipo, subtipos e valores de habilidades originais; muda de tamanho e recebe armas naturais, armadura natural, deslocamentos e ataques extraordinários da forma assumida, mas mantém suas qualidades especiais e ataques especiais originais, exceto olhar e sopro. Também conserva suas habilidades similares à magia e sobrenaturais e recebe +10 em Disfarces para usar a mudança como disfarce. Exemplo do livro: a aranea pode assumir a aparência de um humanoide específico Pequeno ou Médio; nessa forma, não pode usar mordida, teia ou veneno."),
GlossaryEntry("Invisibilidade e camuflagem", "Invisibilidade impede a visão normal, mas não torna a criatura automaticamente indetectável: som, cheiro, rastros e sentidos especiais ainda podem revelar sua presença. Camuflagem dificulta localizar ou atingir a criatura."),
                GlossaryEntry("Telepatia", "Permite comunicar-se mentalmente com outras criaturas dentro do alcance e nas condições indicadas. Não significa, por si só, ler pensamentos ou controlar a mente."),
                GlossaryEntry("Psiquismo", "Habilidades similares à magia geradas pelo poder mental da criatura. Em geral podem ser usadas sem limite diário, mas continuam sujeitas às condições e aos efeitos indicados no verbete. Exemplo do livro: um githzerai apresentado no capítulo possui psiquismo 3/dia, com efeitos como despedaçar, pasmar e queda suave; nesse caso, a ficha limita os usos, apesar da tendência geral descrita no glossário."),
                GlossaryEntry("Ataque visual", "É ativado quando o oponente olha para os olhos da criatura. O alcance padrão é 9 m, salvo indicação diferente; o efeito e o teste de resistência (geralmente Fortitude ou Vontade) são definidos no verbete. Os alvos na área fazem o teste no início de cada turno. Desviar o olhar dá 50% de chance de evitar o teste, mas concede cobertura à criatura; fechar os olhos ou virar-se concede cobertura total. A criatura também pode ativar o ataque como ação de ataque contra um alvo. Exemplo do livro: o ghaele, em forma humanoide, mata criaturas malignas com 5 DV ou menos a até 18 m (Vontade CD 18); mesmo quem passa no teste sofre medo por 2d10 rodadas. Criaturas não malignas ou com mais de 5 DV também fazem Vontade CD 18 para evitar o medo."),
                GlossaryEntry("Ataques sônicos", "Normalmente seguem as regras de dispersão, com alcance medido a partir da criatura atacante. Ensurdecer o alvo depois da emissão não anula o efeito. Proteger a audição antecipadamente pode permitir testes contra efeitos sônicos de ação mental, mas não contra efeitos que causam dano. Exemplo do livro: o rugido de um leonal cria um cone de 18 m, reproduz parte dos efeitos de palavra sagrada e causa 2d6 pontos adicionais de dano sônico (Fortitude CD 20 anula o efeito)."),
                GlossaryEntry("Distração (Ext)", "Qualquer criatura viva vulnerável ao dano do enxame que comece seu turno no mesmo espaço deve passar em Fortitude (CD 10 + metade dos DV do enxame + modificador de Constituição) ou ficará enjoada por 1 rodada. Conjurar ou concentrar-se em uma magia dentro do enxame exige Concentração CD 20 + nível da magia. Exemplo prático: um aventureiro que começa seu turno cercado por um enxame de morcegos pode sofrer enjoo e ter dificuldade para conjurar, mesmo que não tenha sido derrubado."),
                GlossaryEntry("Presença Aterradora (Ext)", "A presença da criatura provoca medo quando ela realiza uma ação dramática, como investir, atacar ou rugir. O verbete determina quais ações ativam o efeito e sua área; em geral o alcance é 9 m e a duração 5d6 rodadas. A habilidade afeta apenas oponentes com menos níveis ou DV que a criatura e permite Vontade (CD 10 + metade dos DV + modificador de Carisma). Quem passa no teste fica imune à presença aterradora daquela criatura por 24 horas. Exemplo prático: quando um dragão ruge diante de aventureiros de nível inferior, os que estiverem na área indicada fazem o teste de Vontade; a condição sofrida em caso de falha é a especificada no verbete."),
                GlossaryEntry("Voo (Ext ou Sob)", "Permite à criatura alçar voo ou aterrissar como ação livre. Se for sobrenatural (Sob), a capacidade deixa de funcionar dentro de um campo antimagia; se for extraordinária (Ext), não é suprimida por esse efeito. O deslocamento, a manobrabilidade e outras limitações aparecem no verbete. Exemplo prático: uma criatura com voo extraordinário pode decolar sem gastar sua ação de movimento; uma criatura cujo voo seja sobrenatural perde essa capacidade enquanto estiver em um campo antimagia."),
                GlossaryEntry("Sentido Aquático (Ext)", "Permite localizar criaturas submersas dentro do alcance indicado, como se a criatura tivesse Sentido Cego. Só funciona debaixo d’água. Exemplo do livro: o sahuagin localiza criaturas submersas a até 9 m, mas não recebe esse benefício em terra firme."),
                GlossaryEntry("Frenesi de Sangue", "Habilidade específica do sahuagin: uma vez por dia, depois de sofrer dano em combate, ele entra em frenesi no turno seguinte e ataca sem controle até morrer ou eliminar o oponente. Recebe +2 em Constituição, +2 em Força e –2 na CA; não pode encerrar o frenesi voluntariamente. Exemplo prático: um sahuagin ferido pode continuar atacando o mesmo inimigo mesmo que a retirada fosse mais segura."),
                GlossaryEntry("Sensibilidade à Água Doce (Ext)", "Qualidade específica do sahuagin. Quando totalmente submerso em água doce que não seja água do mar, deve passar em Fortitude CD 15 ou ficará fatigado; mesmo se passar, repete o teste a cada 10 minutos em que continuar submerso. Exemplo prático: atravessar um rio pode obrigar o sahuagin a fazer testes repetidos enquanto permanecer completamente submerso."),
                GlossaryEntry("Cegueira sob Luz (Ext)", "Qualidade específica do sahuagin: uma exposição repentina a luz brilhante, como luz solar ou a magia luz do dia, deixa-o cego por 1 rodada e ofuscado nas rodadas seguintes enquanto permanecer sob a luz. Exemplo prático: sair de uma caverna escura diretamente para a luz do sol desencadeia o efeito."),
                GlossaryEntry("Falar com Tubarões (Ext)", "O sahuagin consegue comunicar-se telepaticamente com tubarões a até 50 m, mas a comunicação se limita a conceitos simples, como comida ou perigo. Exemplo prático: um sahuagin pode alertar um tubarão próximo sobre a presença de alimento, mas não manter uma conversa complexa."),
                GlossaryEntry("Nuvem de Tinta (Ext)", "Algumas criaturas aquáticas expelem uma nuvem de tinta que concede camuflagem total e pode ajudá-las a escapar. O tamanho, a duração, a frequência e os efeitos adicionais variam conforme a criatura. Exemplo do livro: o kraken cria uma nuvem com 24 m de dispersão uma vez por minuto, como ação livre; criaturas dentro dela sofrem os efeitos da escuridão total. Lulas e tojanidas têm versões diferentes."),
                GlossaryEntry("Propulsão (Ext)", "Permite à criatura aquática arremessar-se para trás em linha reta como ação de rodada completa, percorrendo o deslocamento indicado sem provocar ataques de oportunidade. Exemplo do livro: a lula percorre 72 m com propulsão; o kraken, 84 m."),
                GlossaryEntry("Ataques de enxame", "Criaturas com o subtipo enxame não fazem ataques corpo a corpo comuns: causam dano automaticamente às criaturas que ocupam o mesmo espaço ao final do deslocamento. O dano depende dos Dados de Vida do enxame. Não ameaçam os espaços ocupados nem provocam ataques de oportunidade com esse ataque; alguns enxames também transmitem veneno, doença ou outros efeitos. Exemplo do livro: um enxame de morcegos causa 1d6 pontos de dano a quem terminar o turno em seu espaço; seus ferimentos também podem provocar sangramento."),
                GlossaryEntry("Ferimento amaldiçoado", "Ataque especial listado pelo Livro dos Monstros. O efeito concreto, a forma de remoção e as condições para curar o ferimento dependem do verbete da criatura; não se deve presumir que todos os ferimentos amaldiçoados tenham a mesma regra. Exemplo do livro: o golem de barro causa um ferimento que não se recupera naturalmente e resiste a magias de cura; curar ferimentos ou cura completa exige um teste de nível de conjurador CD 26 para funcionar."),
                GlossaryEntry("Sangramento", "Ataque especial listado pelo Livro dos Monstros. A quantidade de dano, frequência, duração e formas de estancar ou curar o sangramento dependem da descrição específica da criatura. Exemplo do livro: o enxame de morcegos faz a vítima perder 1 PV por rodada; um teste de Cura CD 10 ou uma magia de cura interrompe o sangramento."),
                GlossaryEntry("Raio e rugido", "São categorias de ataques especiais encontradas em determinados monstros. Alcance, área, dano, frequência, CD e tipo de teste são definidos pelo verbete; não existe um único conjunto de regras aplicável a todos eles. Exemplos do livro: o ghaele dispara raios de luz a até 100 m, causando 2d12 pontos de dano; o andro-esfinge pode rugir três vezes por encontro, com efeitos diferentes a cada rugido, incluindo medo, paralisia e dano de Força."),
                GlossaryEntry("Magias e habilidades similares à magia", "Algumas criaturas conjuram magias como personagens ou reproduzem efeitos mágicos por habilidades similares à magia. Consulte a lista, o nível de conjurador, a frequência de uso, a ação necessária e a Resistência à Magia indicada no verbete."),
                GlossaryEntry("Invocar criaturas", "Permite chamar criaturas da mesma raça como se fosse invocar criaturas, mas com chance limitada de sucesso indicada no verbete. Em geral, as criaturas invocadas retornam após 1 hora e não podem usar sua própria habilidade de invocação nesse período; não concedem pontos de experiência quando derrotadas. Exemplo prático: se a tentativa falhar na rolagem percentual, ninguém atende ao chamado; se funcionar, o aliado permanece por até 1 hora, conforme a descrição."),
                GlossaryEntry("Imunidade a efeitos", "A imunidade indicada impede que a criatura seja afetada por uma categoria específica, como veneno, sono, paralisia, doença, acertos críticos ou efeitos de ação mental. Não se estende automaticamente a categorias não mencionadas."),
                GlossaryEntry("Características de morto-vivo", "Mortos-vivos são imunes a diversos efeitos que afetam criaturas vivas, não possuem Constituição e usam regras próprias para Dados de Vida, cura, energia positiva/negativa e testes de resistência."),
                GlossaryEntry("Nuvem Negra (Ext)", "O achaierai pode expelir uma nuvem de fumaça tóxica três vezes por dia. Criaturas (exceto outros achaierai) num raio de 3 m sofrem 2d6 pontos de dano e fazem Fortitude CD 15; quem falha fica sob efeito de insanidade por 3 horas. Este é o efeito específico do achaierai, não uma regra geral para nuvens de fumaça."),
                GlossaryEntry("Drenar Sabedoria (Sob)", "Reduz permanentemente a Sabedoria da vítima, conforme o ataque e o verbete da criatura. O allip causa 1d4 pontos de dano permanente de Sabedoria ao acertar com seu toque incorpóreo e recebe 5 PV temporários por acerto; a lamia também causa 1d4 pontos permanentes, mas não recupera nem recebe PV por isso. Não confunda dano temporário com dano permanente de atributo."),
                GlossaryEntry("Sensibilidade à Luz (Ext)", "Algumas criaturas subterrâneas sofrem penalidades quando expostas à luz intensa ou à luz solar. A condição varia conforme a espécie: o verbete pode indicar pasmo ou ofuscamento, além de especificar se a luz do dia também desencadeia o efeito. Consulte sempre a criatura; não se deve aplicar uma penalidade única a todos os monstros com essa característica."),
                GlossaryEntry("Aura de Proteção (Sob)", "No exemplo dos anjos, a aura beneficia criaturas aliadas num raio de 6 m, concedendo +4 de bônus de deflexão na CA e +4 de bônus de resistência nos testes contra ataques e efeitos de seres malignos. Também combina efeitos de círculo mágico contra o mal e globo de invulnerabilidade menor. Pode ser dissipada, mas o anjo pode recriá-la como ação livre no turno seguinte. Os benefícios e o nível de conjurador dependem do verbete."),
                GlossaryEntry("Aura Antinatural (Sob)", "A presença de certas criaturas sobrenaturais é percebida por animais. No exemplo das aparições, animais num raio de 9 m evitam aproximar-se voluntariamente e entram em pânico se forem forçados a fazê-lo; permanecem apavorados enquanto estiverem na área. Não é uma aura de medo universal contra personagens."),
                GlossaryEntry("Aparência Horripilante (Sob)", "A aparência de algumas criaturas causa dano ou condições a quem as vê, mas o efeito varia muito. A bruxa do mar exige Fortitude CD 13 ou causa 2d8 pontos de dano temporário de Força; o fantasma pode causar 1d4 pontos temporários de dano a Força, Destreza e Constituição, cada um, se a vítima falhar. A CD, o alcance e os atributos afetados devem ser lidos no verbete específico."),
                GlossaryEntry("Ladrar (Sob)", "No exemplo do cão yeth, uivar ou latir afeta criaturas num raio de 90 m, exceto outros extraplanares malignos. Vontade CD 11 evita ficar apavorado por 2d4 rodadas; quem for afetado fica imune ao ladrar daquele mesmo cão por 24 horas. O efeito é sônico, de ação mental e de medo."),
                GlossaryEntry("Dança da Destruição (Sob)", "Habilidade coletiva dos vrocks: pelo menos três demônios precisam unir as mãos e dançar/cantar durante três rodadas. Ao concluir, liberam energia num raio de 30 m, causando 20d6 pontos de dano; Reflexos CD 15 reduz à metade. Atordoar, paralisar ou matar um dos participantes interrompe a dança. Esses números pertencem ao verbete dos vrocks."),
                GlossaryEntry("Esporos (Ext)", "O vrock pode expelir esporos uma vez a cada três rodadas, como ação livre. Criaturas adjacentes sofrem 1d8 pontos de dano inicialmente e, depois, 1d4 pontos por rodada durante 10 rodadas. O livro indica formas específicas de interromper ou matar os esporos, como retardar envenenamento, benção, neutralizar venenos, remover doenças ou água benta."),
                GlossaryEntry("Insanidade (Ext)", "A insanidade racial dos derro altera seus testes de Vontade: eles usam o modificador de Carisma no lugar de Sabedoria e são imunes a efeitos de confusão e insanidade. Segundo o verbete, a sanidade de um derro só pode ser restaurada por milagre ou desejo. Não é uma regra aplicável a todas as criaturas insanas."),
                GlossaryEntry("Enxurrada (Ext)", "O toque de um elemental da água apaga chamas mundanas expostas de tamanho Grande ou menor, como tochas, fogueiras e lampiões. Também pode dissipar fogo mágico que toque, como dissipar magia, usando nível de conjurador igual aos Dados de Vida do elemental."),
                GlossaryEntry("Deslizar na Terra (Ext)", "O elemental da terra pode atravessar rocha, solo e praticamente qualquer terreno, exceto metal, como se estivesse nadando. Não deixa túnel, buraco ou sinal da passagem. O verbete também descreve uma interação específica com mover terra: se estiver submerso no terreno afetado, pode ser arremessado a 9 m e atordoado por 1 rodada, salvo sucesso em Fortitude CD 15."),
                GlossaryEntry("Incendiar (Ext)", "A pancada do elemental do fogo causa dano de concussão e dano de fogo por causa das chamas de seu corpo. O verbete apresenta a condição e o teste de resistência aplicável às criaturas atingidas; consulte a ficha do elemental para a CD e os detalhes, sem presumir que essa habilidade tenha o mesmo efeito em outros monstros."),
                GlossaryEntry("Possessão (Sob)", "O fantasma etéreo pode tentar possuir uma criatura do Plano Material uma vez por rodada. Precisa estar manifestado e entrar no espaço do alvo; o deslocamento não provoca ataque de oportunidade. A vítima resiste com Vontade, usando a CD do verbete; se falhar, o fantasma desaparece dentro do corpo. O efeito segue as regras específicas do fantasma e é semelhante a recipiente arcano, mas não exige receptáculo."),
                GlossaryEntry("Toque da Corrupção (Sob)", "No exemplo do fantasma, um toque incorpóreo contra uma criatura viva causa 1d6 pontos de dano. Contra oponentes etéreos, o fantasma aplica seu modificador de Força nas jogadas de ataque e dano; contra oponentes corpóreos, usa o modificador de Destreza apenas nas jogadas de ataque. Não confunda com o Olhar da Corrupção, que é outro ataque do mesmo tipo de criatura."),
                GlossaryEntry("Sentir Eletricidade (Ext)", "O lagarto elétrico detecta automaticamente qualquer descarga elétrica num raio de 30 m. A descrição não concede, por si só, a capacidade de detectar criaturas ou objetos que não estejam produzindo uma descarga."),
                GlossaryEntry("Choque Atordoante (Sob)", "O lagarto elétrico pode disparar este choque uma vez por rodada contra um único oponente a até 1,5 m. Causa 2d8 pontos de dano por contusão; um teste de Reflexos CD 12 reduz o dano à metade. A CD é baseada em Constituição. Exemplo: se um aventureiro adjacente falhar no teste, sofre 2d8 de dano por contusão; se passar, sofre metade."),
                GlossaryEntry("Choque Letal (Sob)", "Dois ou mais lagartos elétricos a até 6 m um do outro podem combinar suas descargas. O choque afeta uma área de 6 m de raio, centrada em qualquer lagarto participante, e causa 2d8 pontos de dano por participante, até o máximo de 12d8. Reflexos reduz o dano à metade; a CD é 10 + o número de lagartos envolvidos. Exemplo: três lagartos participantes causam 6d8 de dano, com CD 13."),
                GlossaryEntry("Toque Paralisante (Sob)", "O efeito depende da criatura. O mohrg paralisa por 1d4 minutos com Fortitude CD 17; o lich pode paralisar permanentemente, e a condição exige magia capaz de remover paralisia ou maldição. No caso do lich, o efeito não pode ser dissipado e a vítima parece morta, embora possa ser identificada por testes de Observar ou Cura. Consulte o verbete para CD e forma de remoção."),
                GlossaryEntry("Mimetismo (Ext)", "O mímico pode assumir a forma de objetos com volume aproximado de 50 metros cúbicos, como um baú grande ou uma porta, mas não altera substancialmente seu tamanho. Sua textura continua áspera e dura; um observador pode perceber o disfarce com um teste de Observar resistido pelo teste de Disfarces do mímico."),
                GlossaryEntry("Patas de Aranha (Ext)", "A criatura consegue escalar superfícies como se estivesse sob efeito da magia patas de aranha. O verbete do vampiro e o de alguns dragões apresentam essa capacidade; o tipo de superfície e as limitações devem ser conferidos na descrição específica."),
                GlossaryEntry("Nuvem de Visco (Ext)", "O abolete submerso pode envolver-se numa nuvem viscosa de 30 cm de espessura. Quem tocar ou inalar a substância precisa passar em Fortitude CD 19 ou perde a capacidade de respirar fora da água por três horas; se for retirado da água, pode morrer sufocado em 2d6 minutos. Novo contato exige outro teste e renova a duração."),
                GlossaryEntry("Muco (Ext)", "O muco do abolete pode transformar gradualmente a pele da vítima numa membrana fina e oleosa em 1d4+1 minutos. A vítima precisa permanecer imersa em água fria e fresca ou sofre 1d12 pontos de dano a cada 10 minutos; o muco também reduz em 1 o bônus de armadura natural. Remover doença antes da transformação terminar reverte o efeito; depois disso, o livro indica apenas cura completa ou cura completa em massa."),
                GlossaryEntry("Murmúrio (Sob)", "O allip resmunga continuamente e cria um efeito hipnótico. Criaturas sãs num raio de 18 m fazem Vontade CD 16 ou ficam sob efeito semelhante a hipnotismo por 2d4 rodadas. É um efeito sônico e uma compulsão de ação mental; quem resiste fica imune ao murmúrio daquele allip por um dia."),
                GlossaryEntry("Enlouquecer (Sob)", "No verbete do allip, um conjurador que tente afetá-lo com detecção de pensamentos, controle mental ou telepatia entra em contato com a mente da criatura e sofre 1d4 pontos de dano temporário de Sabedoria. A habilidade não é uma penalidade geral contra qualquer magia."),
                GlossaryEntry("Adesão (Ext)", "A habilidade varia conforme a criatura. O stirge adere ao corpo após acertar um ataque de toque, ficando preso e perdendo o bônus de Destreza na CA; o arminho atroz crava a mordida e causa dano automaticamente a cada rodada até ser removido por um teste resistido de Agarrar. Não confunda essas versões com o adesivo do mímico ou com o escudo aderente dos kuo-toa."),
                GlossaryEntry("Aderente (Ext)", "O mímico produz um adesivo que prende automaticamente criaturas atingidas por seus ataques e também pode prender armas que o acertem. O verbete informa Reflexos CD 16 para evitar que a arma fique presa e Força CD 16 para soltá-la; álcool dissolve a substância. Os kuo-toa possuem outra versão, aplicada ao escudo, que pode prender armas e atacantes que falhem contra ele."),
                GlossaryEntry("Aura de Ameaça (Sob)", "A aura dos arcontes afeta criaturas hostis num raio de 6 m quando o arconte luta ou fica enfurecido. Vontade evita o efeito; quem falha sofre –2 nas jogadas de ataque, na CA e nos testes de resistência durante 24 horas ou até atingir o arconte. Quem resiste fica imune à aura daquele arconte por 24 horas. A CD varia conforme o tipo de arconte."),
                GlossaryEntry("Raios Ópticos (Sob)", "Beholders e gauth projetam raios pelos olhos, cada um reproduzindo um efeito mágico diferente. Quantidade de raios, alcance, nível de conjurador, CD e efeitos variam conforme a criatura. Exemplo do livro: o gauth possui seis raios com alcance de 30 m e CD 14; o beholder possui dez raios com alcance de 45 m e CD 17. Consulte cada lista de raios para saber o teste e o efeito de cada um."),
                GlossaryEntry("Salto (Ext)", "O bulette pode saltar durante o combate para atacar com as quatro garras em vez de apenas duas. Nesse turno, cada garra recebe o bônus de ataque indicado em seu verbete, mas a criatura não pode realizar a mordida na mesma rodada."),
                GlossaryEntry("Tentáculos Paralisantes (Ext)", "O chuul pode arrastar para seus tentáculos uma vítima que já prendeu com a garra. Os tentáculos agarram sem causar dano, mas secretam uma substância paralisante: Fortitude CD 19 evita a paralisia por 6 rodadas. Enquanto a vítima permanecer presa, sofre também 1d8+2 pontos de dano por rodada das mandíbulas do chuul."),
                GlossaryEntry("Destruição (Sob)", "No exemplo do nalfeshnee, a habilidade cria uma explosão de luz profana três vezes por dia. Na rodada seguinte à ativação, ela explode num raio de 18 m; Vontade CD 22 evita ficar pasmo por 1d10 rodadas. Outros demônios são imunes. Não confunda esta habilidade com a Dança da Destruição dos vrocks."),
                GlossaryEntry("Ferimento Infernal (Sob)", "O diabo barbado e o diabo de chifres causam um ferimento persistente que retira 2 PV adicionais por rodada, não se cura naturalmente e resiste a magias de cura. O teste de Cura ou o teste de nível de conjurador exigido para a magia depende do diabo: CD 16 no barbazu e CD 24 no diabo de chifres. É uma habilidade sobrenatural da criatura, não da arma."),
                GlossaryEntry("Barba (Ext)", "No diabo barbado, quando ambas as garras atingem o mesmo oponente, a barba também o atinge automaticamente. Além do dano, Fortitude CD 16 evita a doença calafrios diabólicos, que causa dano temporário de Força diariamente até a vítima obter três sucessos consecutivos, ser curada por magia ou morrer."),
                GlossaryEntry("Frenesi de Batalha (Ext)", "O diabo barbado pode entrar num frenesi semelhante à Fúria do bárbaro. No exemplo do livro, recebe +4 em Força, +4 em Constituição, +2 de bônus de moral em Vontade e –2 na CA durante 6 rodadas, sem sofrer efeitos colaterais ao terminar."),
                GlossaryEntry("Raio Elétrico (Sob)", "O gavião-seta dispara uma rajada de energia elétrica uma vez por rodada, com alcance de 15 m. O dano e demais parâmetros dependem do tamanho/estágio da criatura e de sua ficha; o alcance e a frequência citados são os do verbete do gavião-seta."),
                GlossaryEntry("Raio de Luz (Ext)", "O arconte luminar dispara raios de luz com alcance de 10 m. No verbete, esse ataque ignora qualquer tipo de Redução de Dano. Não confunda com os raios ópticos mágicos de beholders e gauth."),
                GlossaryEntry("Beijo (Sob)", "O vargouille só pode beijar uma vítima paralisada, após acertá-la com um ataque de toque corpo a corpo. Fortitude CD 15 evita a transformação que, se não for interrompida, pode converter a vítima em outro vargouille nas 24 horas seguintes. O verbete descreve etapas e formas específicas de interromper o processo."),
                GlossaryEntry("Trinado (Sob)", "O verme do gelo emite um som que afeta criaturas num raio de 30 m, exceto outros vermes do gelo. Vontade CD 17 evita ficar atordoado enquanto o verme continua trinando e por 1d4 rodadas depois que para. Ser atacado ou chacoalhado violentamente concede um novo teste; quem resiste fica imune ao trinado daquele verme por 24 horas."),
                GlossaryEntry("Passeio Etéreo (Sob)", "Permite transitar entre o Plano Etéreo e o Plano Material. A forma exata varia: salteadores e saqueadores etéreos podem atravessar para o Material como parte de uma ação de movimento e retornar como ação livre, mas só permanecem uma rodada no Material antes de voltar. Outros monstros podem seguir a magia passeio etéreo de modo diferente; confira o verbete."),
                GlossaryEntry("Dano Dobrado contra Objetos (Ext)", "Entes e árvores animadas causam o dobro do dano quando realizam um ataque total contra um objeto ou estrutura. A habilidade não dobra automaticamente o dano contra criaturas."),
                GlossaryEntry("Arrebatar (Ext)", "O dragão-tartaruga pode agarrar e manter criaturas presas com suas garras ou mordida, causando dano por rodada conforme o tamanho da vítima. No verbete, uma criatura arrebatada também pode ser arremessada de 27 m de altura, sofrendo 9d6 pontos de dano. Os modificadores de agarrar e os danos variam conforme o ataque e o tamanho do alvo."),
                GlossaryEntry("Maestria Aquática (Ext)", "O elemental da água recebe +1 nas jogadas de ataque e dano quando ele e o oponente estão em contato com a água. Se o elemental ou o adversário estiver em terra firme, o elemental sofre –4 nas jogadas de ataque e dano. Esses modificadores não estão incluídos no bloco de estatísticas."),
                GlossaryEntry("Maestria Aérea (Ext)", "Todas as criaturas aéreas sofrem –1 nas jogadas de ataque e dano contra elementais do ar. A penalidade representa a superioridade da criatura no combate aéreo."),
                GlossaryEntry("Maestria Terrestre (Ext)", "O elemental da terra recebe +1 nas jogadas de ataque e dano quando ele e o adversário estão em contato com o solo. Se o oponente estiver voando ou nadando, o elemental sofre –4 nas jogadas de ataque e dano; os modificadores não estão incluídos nas estatísticas."),
                GlossaryEntry("Vórtice (Sob)", "O elemental da água pode transformar-se num redemoinho enquanto está submerso, uma vez a cada 10 minutos, permanecendo nessa forma por 1 rodada para cada 2 Dados de Vida. Move-se pela água com seu deslocamento de natação; criaturas menores que toquem ou entrem no redemoinho podem ser aprisionadas. As dimensões e a CD dependem do tamanho do elemental."),
                GlossaryEntry("Vendaval (Sob)", "O elemental do ar pode transformar-se num vendaval uma vez a cada 10 minutos, permanecendo nessa forma por 1 rodada para cada 2 Dados de Vida. Nessa forma, desloca-se com seu voo sobre o ar ou a superfície; dimensões e efeitos dependem do tamanho do elemental."),
                GlossaryEntry("Empurrar (Ext)", "O elemental da terra pode iniciar a manobra Encontrão sem provocar ataques de oportunidade. Os modificadores de combate de Maestria Terrestre também se aplicam aos testes resistidos de Força."),
                GlossaryEntry("Toque Pútrido (Sob)", "A múmia transmite uma doença sobrenatural por pancada: Fortitude CD 16, incubação de 1 minuto e dano de 1d6 em Constituição e 1d6 em Carisma. O livro a descreve também como uma maldição: magias de Conjuração [Cura] exigem teste de nível de conjurador CD 20 para funcionar, e a remoção depende das magias indicadas no verbete."),
                GlossaryEntry("Animar Árvores (SM)", "O ente pode animar árvores num raio de 54 m, sem limite diário, mas controla no máximo duas ao mesmo tempo. Uma árvore normal precisa de uma ação de rodada completa para se desenraizar; depois se desloca a 3 m e luta como um ente. As árvores deixam de se mover se o ente for incapacitado ou sair do alcance, e também são vulneráveis a fogo. O livro identifica o efeito com a magia carvalho vivo (12º nível de conjurador)."),
                GlossaryEntry("Assombrar os Sonhos (Sob)", "A bruxa da noite usa sua pedra-coração para se tornar etérea e invadir os sonhos de criaturas Caóticas ou Más. Ela paira sobre a vítima até o amanhecer; ao despertar, a vítima perde 1 ponto de Constituição. Segundo o verbete, somente outra criatura etérea pode impedir a intrusão, confrontando e derrotando a bruxa."),
                GlossaryEntry("Aura Degradante (Sob)", "A aura dos vultos noturnos emana energia profana num raio de 6 m, como a magia profanar. Mortos-vivos na área, inclusive o próprio vulto, recebem +2 profano nas jogadas de ataque e dano e nos testes de resistência, além de 2 PV adicionais por Dado de Vida; testes de Carisma para expulsar mortos-vivos sofrem –6. A aura não pode ser dissipada normalmente e interage com áreas consagradas ou santificadas conforme o verbete."),
                GlossaryEntry("Aura Ígnea (Ext)", "O magmin aquece intensamente o entorno. Criaturas num raio de 6 m devem fazer Fortitude CD 12 ou sofrer 1d6 pontos de dano por rodada. A CD é baseada em Constituição. Exemplo: aproximar-se de um magmin pode causar dano mesmo sem ele acertar um ataque corpo a corpo."),
                GlossaryEntry("Aversão à Luz do Dia (Ext)", "Os vultos noturnos sofrem –4 nas jogadas de ataque, testes de resistência e testes de perícia quando expostos à luz natural do dia. O Livro dos Monstros distingue expressamente a luz natural da magia luz do dia: a magia, por si só, não ativa esta aversão."),
                GlossaryEntry("Coaxar Atordoante (Sob)", "O slaad vermelho pode emitir esse som uma vez por dia. Criaturas num raio de 6 m, exceto outros slaad, devem obter sucesso em Fortitude CD 16 ou ficam atordoadas por 1d3 rodadas. A CD é baseada em Constituição."),
                GlossaryEntry("Combustão (Ext)", "O toque do magmin pode incendiar roupas ou aquecer armaduras. A criatura tocada faz Reflexos CD 12; se falhar, sofre 1d8 pontos adicionais de dano por fogo durante 1d4+2 rodadas depois do último golpe bem-sucedido do magmin. O magmin também pode incendiar materiais inflamáveis com o toque. A CD é baseada em Constituição."),
                GlossaryEntry("Destruir Armaduras (Ext)", "O bebilith precisa acertar o mesmo oponente com as duas garras para arrancar a armadura que ele estiver usando. O ataque causa 4d6+18 pontos de dano à armadura; criaturas sem armadura não são afetadas. Uma armadura reduzida a 0 PV é destruída, enquanto uma danificada pode ser consertada com Ofícios (armeiro)."),
                GlossaryEntry("Drenar Magia (Sob)", "O vulto alado pode enfraquecer uma arma, armadura ou escudo mágico com um ataque de toque. O item faz Fortitude CD 12; se falhar, perde 1 ponto de bônus de melhoria. Ao perder todos os bônus, torna-se obra-prima e perde suas habilidades especiais. O verbete permite reverter o efeito com dissipar o mal sobre o item, dentro do prazo indicado, mediante teste de nível de conjurador CD 29."),
                GlossaryEntry("Esmagar Itens (Sob)", "O andarilho noturno pode destruir armas e itens de tamanho Grande ou menor, inclusive mágicos, mas não artefatos, se conseguir segurá-los e esmagá-los. Para tomar um item empunhado, primeiro precisa vencer uma manobra Desarmar; depois, o item faz Fortitude CD 34 para resistir à destruição. A CD é baseada em Força."),
                GlossaryEntry("Estouro da Manada (Ext)", "Quando um rebanho de bisões fica apavorado, foge em grupo numa direção aleatória, sempre se afastando do perigo. Atropela criaturas de tamanho Grande ou menor no caminho e causa 1d12 pontos de dano para cada cinco bisões; Reflexos CD 16 reduz o dano à metade. A CD é baseada em Força."),
                GlossaryEntry("Faro Aguçado (Ext)", "O tubarão atroz percebe criaturas pelo Faro num raio de 54 m e detecta sangue na água a até 1,5 km. Esses alcances são próprios desse verbete e não substituem o alcance básico do Faro nem devem ser generalizados para todos os tubarões."),
                GlossaryEntry("Ferrugem (Ext)", "O monstro da ferrugem enferruja metal ao acertá-lo com as antenas; um toque pode destruir instantaneamente um cubo de metal com 3 m de aresta. Armas, armaduras e outros itens metálicos encantados fazem Reflexos CD 17 para não serem dissolvidos. Uma arma metálica que acerte o monstro também é corroída; armas de madeira, pedra e outros materiais não metálicos são imunes. As CDs incluem +4 de bônus racial e são baseadas em Constituição."),
                GlossaryEntry("Flautas (Sob)", "As flautas mágicas do sátiro afetam criaturas numa área de 18 m, exceto outros sátiros. O sátiro escolhe entre enfeitiçar pessoa, sono ou medo; os alvos fazem Vontade CD 13. Quem obtiver sucesso contra um efeito fica imune ao mesmo conjunto de flautas por 24 horas. Nas mãos de outras criaturas, as flautas não têm poderes especiais."),
                GlossaryEntry("Garras de Fumaça (Ext)", "Quando está na forma gasosa, o belker pode engolfar sem provocar ataques de oportunidade uma criatura de tamanho Médio ou menor. O alvo faz Fortitude CD 14 para não inalar parte do belker; se falhar, a fumaça se solidifica como uma garra dentro do corpo e causa 3d4 pontos de dano por rodada. A vítima pode repetir o teste de Fortitude a cada rodada para expelir a ameaça."),
                GlossaryEntry("Harmonia Destrutiva (Sob)", "O destrachan emite energia sônica em cone, com alcance indicado de 24 m; o verbete descreve os alvos na área de 9 m. Pode ajustar a harmonia: Carne causa 4d6 de dano às criaturas (Reflexos CD 15 reduz à metade); Nervos causa 6d6 de dano por contusão (Reflexos CD 15 reduz à metade); Material escolhe madeira, pedra, metal ou vidro, e objetos desse material fazem Fortitude CD 15 ou são estilhaçados. Objetos com até 30 PV são os alvos primários. As CDs são baseadas em Carisma."),
                GlossaryEntry("Implante (Ext)", "A habilidade varia conforme a criatura. O devorador de aranhas deposita ovos em criaturas paralisadas Grandes ou maiores; o filhote emerge após seis semanas e devora o hospedeiro. O slaad vermelho pode implantar um ovo ao acertar com a garra (Fortitude CD 16 evita); ele choca após uma semana, e remover doenças ou Cura CD 25 pode extraí-lo, embora tentativas de Cura causem 1d4 de dano. O xill também implanta ovos em criaturas paralisadas, como ação padrão; a incubação leva cerca de 90 dias, e a extração segue o procedimento indicado no verbete. Não trate prazos e CDs como universais."),

                GlossaryEntry("ND — Nível de Desafio", "Estimativa da dificuldade que a criatura representa para um grupo de personagens. É uma referência para o Mestre, não o nível de personagem da criatura."),
                GlossaryEntry("DV — Dados de Vida", "Quantidade e tipo de dados usados para determinar os pontos de vida da criatura. Exemplo: 4d8."),
                GlossaryEntry("PV — Pontos de Vida", "Quantidade de dano que a criatura pode sofrer antes de morrer ou ser destruída, conforme suas regras."),
                GlossaryEntry("CA — Classe de Armadura", "Número que um atacante precisa igualar ou superar para acertar a criatura. A ficha também informa CA de toque e CA de surpresa."),
                GlossaryEntry("CA de toque", "Não considera armadura, escudo ou armadura natural, mas outros modificadores aplicáveis continuam valendo."),
                GlossaryEntry("CA de surpresa", "CA quando a criatura está desprevenida. Nessa situação, normalmente não aplica seu bônus de Destreza à CA."),
                GlossaryEntry("BBA — Bônus Base de Ataque", "Parcela do bônus de ataque determinada pelos Dados de Vida e pela progressão da criatura."),
                GlossaryEntry("Agarrar (modificador)", "Modificador usado nas jogadas de ataque de agarrar, incluindo BBA, modificador de Força e modificador de tamanho."),
                GlossaryEntry("Fort, Ref e Von", "Abreviações de Fortitude, Reflexos e Vontade: os três tipos de testes de resistência."),
                GlossaryEntry("Espaço e alcance", "Espaço representa a área ocupada pela criatura em combate; alcance indica até onde ela pode realizar ataques corpo a corpo.")
            )
        }
        RulesGlossaryType.SPELLBOOK -> {
            title = "Ajuda do Grimório"
            introduction = "Os componentes indicam o que é necessário para conjurar uma magia. Uma magia pode exigir um ou vários componentes."
            entries = listOf(
                GlossaryEntry("V — Verbal", "A conjuração exige palavras pronunciadas em voz firme. Em geral, não é possível usar o componente verbal quando não se pode falar ou produzir os sons necessários."),
                GlossaryEntry("G — Gestual", "A conjuração exige gestos precisos com pelo menos uma mão livre. Uma mão ocupada ou presa pode impedir esse componente."),
                GlossaryEntry("M — Material", "A conjuração exige uma substância ou objeto físico indicado pela magia. O componente é consumido durante a conjuração; componentes com custo indicado precisam ter o valor especificado."),
                GlossaryEntry("F — Foco", "A magia exige um objeto específico como foco. Diferentemente de um componente material, o foco não é consumido pela conjuração, salvo indicação expressa da magia."),
                GlossaryEntry("FD — Foco Divino", "É um foco ligado à fé do conjurador, normalmente um símbolo sagrado ou profano. Não é consumido pela conjuração, salvo indicação expressa."),
                GlossaryEntry("XP — Custo em experiência", "A conjuração exige que o personagem gaste a quantidade de pontos de experiência indicada. Esse custo é pago além de quaisquer outros componentes.")
            )
        }
    }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(title, fontWeight = FontWeight.Bold) },
        text = {
            Column(
                modifier = Modifier.fillMaxWidth().verticalScroll(rememberScrollState()),
                verticalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                Text(introduction, style = MaterialTheme.typography.bodyMedium)
                entries.forEach { entry ->
                    Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
                        Text(entry.term, style = MaterialTheme.typography.titleSmall, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                        Text(entry.explanation, style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
                    }
                }
            }
        },
        confirmButton = { TextButton(onClick = onDismiss) { Text("Entendi") } }
    )
}
